SELECT CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END AS hire_cohort, COUNT(*) AS employee_count, MAX(salary) - MIN(salary) AS salary_range FROM employees WHERE LOWER(email) LIKE '%avi%' GROUP BY CASE WHEN YEAR(hire_date) < 2024 THEN 'before_2024' WHEN YEAR(hire_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING salary_range < 69;
